from unittest.mock import patch

import sentry_sdk
from cronutils.error_handler import BundledError
from sentry_sdk.transport import Transport

from libs import sentry as libs_sentry
from libs.sentry import (get_sentry_client, send_sentry_warning, SentryErrorHandler,
    SentryTimerWarning, SentryUtils)
from tests.common import CommonTestCase

# This file was entirely generated by claude opus 5.5, reviewed by Eli Jones

# Background: SentryUtils.report_* used to return cronutils' ErrorSentry, which called
# sentry_sdk.init every time one was created (and SentryTimerWarning did the same in __init__).
# sentry_sdk.init replaces the process-wide "global" client, the one that Django, Celery, uncaught
# exceptions, and any sentry call outside a report_* block report to. That caused three bugs:
#   1. Client options set at startup in django_settings (ignore_errors, any scrubbing) were silently
#      dropped after the first report_* call, because the replacement client had default options.
#   2. Every later error in the process went to whichever DSN was used most recently.
#   3. Tags were set on a shared scope, so they stuck to later, unrelated events.
# Most tests here guard against one of those coming back. The rest check that SentryErrorHandler
# still behaves like cronutils' ErrorSentry, because existing callers depend on that behavior.
#
# These tests use SentryErrorHandler directly: make_error_sentry (and so SentryUtils.report_*)
# returns cronutils' null_error_handler when running tests, so it would test nothing.


GLOBAL_DSN = "https://global@o0.ingest.sentry.io/1"
PROCESSING_DSN = "https://processing@o0.ingest.sentry.io/2"
REAL_SENTRY_CLIENT_OPTIONS = libs_sentry.sentry_client_options


class CapturingTransport(Transport):
    """ Records (dsn, event) instead of sending. Recording the DSN is what lets tests check which
    client (and therefore which Sentry project) an event went to, without any network access. """
    sent: list[tuple[str, dict]] = []

    def capture_envelope(self, envelope):
        assert self.options is not None
        for item in envelope.items:
            if item.type == "event" and item.payload.json is not None:
                self.sent.append((self.options["dsn"], item.payload.json))


def capturing_client_options() -> dict:
    # The real options plus a capturing transport, so the clients under test are configured the same
    # way production clients are (that is the point of test_clients_are_cached_and_keep_shared_options).
    return {**REAL_SENTRY_CLIENT_OPTIONS(), "transport": CapturingTransport}


def fake_dsn_from_string(sentry_type: str) -> str:
    # Mirrors production: the webserver has its own DSN, every other type shares the processing DSN.
    # (Real DSNs are deployment config, and may be empty or real in a development environment.)
    return GLOBAL_DSN if sentry_type == SentryUtils.types.webserver else PROCESSING_DSN


class TestSentryClients(CommonTestCase):
    """ SentryUtils must never replace the process-wide (global) sentry client, they activate the
    client for their sentry type in a new scope. """

    def setUp(self):
        super().setUp()
        self.patchers = [
            patch.object(libs_sentry, "sentry_client_options", capturing_client_options),
            patch.object(libs_sentry, "get_dsn_from_string", fake_dsn_from_string),
        ]
        for patcher in self.patchers:
            patcher.start()

        CapturingTransport.sent = []
        # Cached clients outlive a test, and one from an earlier test could have a different transport.
        libs_sentry._CACHED_SENTRY_CLIENTS.clear()
        # Install a known global client (the test process's real one comes from django_settings, with
        # whatever DSN this environment has) so tests can assert that it is never replaced.
        self.original_global_client = sentry_sdk.get_global_scope().client
        self.global_client = sentry_sdk.Client(GLOBAL_DSN, **capturing_client_options())
        sentry_sdk.get_global_scope().set_client(self.global_client)

    def tearDown(self):
        # The global client is process-wide state, other tests in this process must get theirs back.
        sentry_sdk.get_global_scope().set_client(self.original_global_client)
        libs_sentry._CACHED_SENTRY_CLIENTS.clear()
        for patcher in self.patchers:
            patcher.stop()
        super().tearDown()

    @property
    def sent_dsns(self) -> list[str]:
        return [dsn for dsn, _ in CapturingTransport.sent]

    ## The global client is never replaced (bugs 1 and 2)

    def test_handler_does_not_replace_global_client(self):
        # The core regression test. The old ErrorSentry replaced the global client on creation, which
        # also covers `with SentryUtils.report_webserver():` blocks that never raise anything.
        with SentryErrorHandler(SentryUtils.types.data_processing):
            raise ValueError("inside")
        self.assertIs(sentry_sdk.get_global_scope().client, self.global_client)
        self.assertIs(sentry_sdk.get_client(), self.global_client)

    def test_timer_warning_does_not_replace_global_client(self):
        # SentryTimerWarning used to call sentry_sdk.init in __init__, and the push notification modules
        # use it as a module-level decorator, so just importing them replaced the global client.
        SentryTimerWarning(SentryUtils.types.data_processing, "message", 10)
        self.assertIs(sentry_sdk.get_client(), self.global_client)

    ## Events go to the right Sentry project

    def test_error_is_sent_to_handler_type_dsn(self):
        # Not replacing the global client must not cost us routing: an error inside a data processing
        # block still has to reach the data processing project, not the webserver project.
        with SentryErrorHandler(SentryUtils.types.data_processing):
            raise ValueError("inside")
        self.assertEqual(self.sent_dsns, [PROCESSING_DSN])
        event = CapturingTransport.sent[0][1]
        self.assertEqual(event["exception"]["values"][-1]["type"], "ValueError")

    def test_timer_warning_is_sent_to_its_type_dsn(self):
        # Timer warnings no longer set a client when they are created, so they have to pick their
        # client when they send. The function_name tag is how we know which function was slow.
        # (Only the after-the-fact warning is tested, the live warning thread is disabled in tests.)
        def slow_function():
            pass
        # a timeout of -1 always triggers the after-the-fact warning
        SentryTimerWarning(SentryUtils.types.data_processing, "too slow", -1)(slow_function)()

        self.assertEqual(self.sent_dsns, [PROCESSING_DSN])
        event = CapturingTransport.sent[0][1]
        self.assertEqual(event["tags"]["function_name"], "slow_function")
        self.assertIs(sentry_sdk.get_client(), self.global_client)

    def test_unconfigured_dsn_reports_to_current_client(self):
        # Some deployments and development environments don't configure every DSN. The old
        # ErrorSentry skipped sentry_sdk.init for an empty DSN, so errors went to the existing client.
        # A client built with an empty DSN would silently drop them instead.
        with patch.object(libs_sentry, "get_dsn_from_string", lambda _sentry_type: ""):
            with SentryErrorHandler(SentryUtils.types.data_processing):
                raise ValueError("inside")
        self.assertEqual(self.sent_dsns, [GLOBAL_DSN])

    ## Tags don't leak into later events (bug 3)

    def test_tags_apply_inside_block_only(self):
        # Callers pass tags like cron_script or forest task details. The old code set them on a shared
        # scope, so they ended up on later, unrelated events, which made filtering in Sentry misleading.
        # This also checks that a warning sent from inside a block goes to that block's project.
        with SentryErrorHandler(SentryUtils.types.data_processing, a_tag="a_value"):
            send_sentry_warning("inside")
        send_sentry_warning("outside")

        (inside_dsn, inside), (outside_dsn, outside) = CapturingTransport.sent
        self.assertEqual(inside_dsn, PROCESSING_DSN)
        self.assertEqual(inside["tags"]["a_tag"], "a_value")
        self.assertEqual(outside_dsn, GLOBAL_DSN)
        self.assertNotIn("a_tag", outside.get("tags", {}))

    def test_send_sentry_warning_tags_do_not_leak(self):
        # Same leak through send_sentry_warning, whose tags are per-event details (participant ids,
        # file names) that would be actively wrong on any later event.
        send_sentry_warning("first", a_tag="a_value")
        send_sentry_warning("second")
        self.assertNotIn("a_tag", CapturingTransport.sent[1][1].get("tags", {}))

    ## SentryErrorHandler behaves like cronutils' ErrorSentry, which existing callers depend on

    def test_handler_records_errors_like_cronutils(self):
        # The handler suppresses the error, records it, and raise_errors raises later. services/cron.py
        # depends on this to report every failing task and still exit with an error.
        handler = SentryErrorHandler(SentryUtils.types.data_processing)
        with handler:
            raise ValueError("inside")
        self.assertEqual(len(handler.errors), 1)
        with self.assertRaises(BundledError), patch("cronutils.error_handler.stderr"):
            handler.raise_errors()

    def test_handler_can_be_reused(self):
        # File processing creates one handler and enters it once per file, and handler(i) is the
        # cronutils way to attach data to each error. Every `with` opens a scope and must close the same
        # one, otherwise the type's client would stay active after the block.
        handler = SentryErrorHandler(SentryUtils.types.data_processing)
        for i in range(3):
            with handler(i):
                raise ValueError(f"inside {i}")
        self.assertEqual(self.sent_dsns, [PROCESSING_DSN] * 3)
        self.assertIs(sentry_sdk.get_client(), self.global_client)

    def test_report_limit_is_per_stacktrace(self):
        # A loop over thousands of files that hits the same bug would otherwise send thousands of
        # identical events and use up the Sentry quota. Errors past the limit are still recorded, so
        # raise_errors reports the full count.
        handler = SentryErrorHandler(SentryUtils.types.data_processing, sentry_report_limit=2)
        for _ in range(3):
            with handler:
                raise ValueError("same stacktrace")
        self.assertEqual(len(CapturingTransport.sent), 2)
        self.assertEqual(len(list(handler.errors.values())[0]), 3)

    ## Client creation and configuration

    def test_type_with_global_dsn_reuses_global_client(self):
        # The global client is already configured for the webserver DSN in the webserver process. A
        # second client for the same DSN would mean a second transport and background thread.
        self.assertIs(get_sentry_client(SentryUtils.types.webserver), self.global_client)

    def test_clients_are_cached_and_keep_shared_options(self):
        # Caching: creating a client per handler is slow (it is why ErrorSentryCache existed), and the
        # forest type shares the data processing DSN so it must get the same client.
        # Options: this is bug 1. Clients for other DSNs must get the shared options, not the defaults.
        client = get_sentry_client(SentryUtils.types.data_processing)
        assert client is not None
        self.assertIs(get_sentry_client(SentryUtils.types.forest), client)  # same DSN
        self.assertEqual(client.options["ignore_errors"], REAL_SENTRY_CLIENT_OPTIONS()["ignore_errors"])
